def is_samepatterns(array1, array2):
    """
    Check whether two arrays follow the same pattern.

    A pattern is the same if:
    1. Both arrays have the same length
    2. Elements at the same positions map consistently

    For example, ["red","green","green"] and ["a", "b", "b"] have the same pattern
    because "red" maps to "a", "green" maps to "b", and the second "green" also maps to "b".
    """
    # Check if arrays have the same length
    if len(array1) != len(array2):
        return False

    # Create mappings from array1 to array2 and vice versa
    mapping1_to_2 = {}
    mapping2_to_1 = {}

    for elem1, elem2 in zip(array1, array2):
        # Check if elem1 already has a mapping
        if elem1 in mapping1_to_2:
            if mapping1_to_2[elem1] != elem2:
                return False
        else:
            mapping1_to_2[elem1] = elem2

        # Check if elem2 already has a mapping (to ensure one-to-one mapping)
        if elem2 in mapping2_to_1:
            if mapping2_to_1[elem2] != elem1:
                return False
        else:
            mapping2_to_1[elem2] = elem1

    return True


# Test cases
