        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = ext_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    g, x0, y0 = ext_gcd(a, b)
    if n % g != 0:
        return None
    x0 *= n // g
    y0 *= n // g
    if a * x0 + b * y0 == n:
        return (x0, y0)
    return None
