def maxAverageOfPath(matrix):
    n = len(matrix)

    # dp[i][j] will store a list of (sum, count) tuples representing all possible
    # (total_cost, num_cells) for paths ending at cell (i, j)
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Initialize starting cell
    dp[0][0] = [(matrix[0][0], 1)]

    # Fill the DP table
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            candidates = []

            # From top cell
            if i > 0:
                for total, count in dp[i-1][j]:
                    candidates.append((total + matrix[i][j], count + 1))

            # From left cell
            if j > 0:
                for total, count in dp[i][j-1]:
                    candidates.append((total + matrix[i][j], count + 1))

            # Keep only non-dominated solutions
            # A solution (s1, c1) dominates (s2, c2) if s1/c1 >= s2/c2
            # We need to keep candidates that could potentially give max average
            non_dominated = []
            for total, count in candidates:
                is_dominated = False
                for existing_total, existing_count in non_dominated:
                    # Check if existing dominates current
                    if existing_total * count >= total * existing_count:
                        is_dominated = True
                        break

                if not is_dominated:
                    # Remove any candidates that current dominates
                    non_dominated = [(t, c) for t, c in non_dominated 
                                   if not (total * c >= t * count)]
                    non_dominated.append((total, count))

            dp[i][j] = non_dominated

    # Find maximum average from all paths ending at bottom-right
    max_avg = 0
    for total, count in dp[n-1][n-1]:
        avg = total / count
        max_avg = max(max_avg, avg)

    return round(max_avg, 1)
```

