def largest_subset(numbers):
    """
    Find the size of the largest subset where every pair is divisible.
    A pair (a, b) is divisible if a divides b or b divides a.
    """
    if not numbers:
        return 0

    n = len(numbers)

    # Sort numbers to make it easier to find divisibility chains
    sorted_nums = sorted(numbers)

    # dp[i] = size of largest subset ending at index i
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            # Check if sorted_nums[j] divides sorted_nums[i]
            if sorted_nums[i] % sorted_nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
