def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    dp_prev = [0] * (m + 1)
    for i in range(1, m + 1):
        dp_prev[i] = 1
    for _ in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        for i in range(1, m + 1):
            total = 0
            for j in range(1, i // 2 + 1):
                total += dp_prev[j]
            dp_curr[i] = total
        dp_prev = dp_curr
    return sum(dp_prev)
```

