def max_sum_increasing_subseq(arr, n, index, k):
    dp = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        if arr[i] > arr[0]:
            dp[0][i] = arr[i] + arr[0]
        else:
            dp[0][i] = arr[i]
    for i in range(1, n):
        for j in range(n):
            if arr[j] > arr[i] and j > i:
                if dp[i - 1][i] + arr[j] > dp[i][j]:
                    dp[i][j] = dp[i - 1][i] + arr[j]
            if dp[i - 1][j] > dp[i][j]:
                dp[i][j] = dp[i - 1][j]
    return dp[index][k]
```

